```
	static async getShardConfiguration(shardsPerCluster = 16): Promise<ResultFunc<GatewayBotInfo | null>> {
		// Obtener información del gateway
		const { data: gateway, hasErrors, errors } = await Shards.getGatewayInformation();
		if (hasErrors || !gateway) {
			return ResultFunc.create(null, errors);
		}

		const totalShards = Shards.normalizeShardCount(gateway.shards, gateway.session_start_limit.max_concurrency);
		const totalClusters = Math.ceil(totalShards / shardsPerCluster);

		const clusterShardList = Shards.chunkShards(totalShards, shardsPerCluster);

		return ResultFunc.create({
			totalShards,
			totalClusters,
			shardsPerCluster,
			clusterShardList,
			sessionStartLimit: gateway.session_start_limit,
			gateway
		});
	}
```

