 * voz — cada una lleva su PROPIA copia dentro de `DBLevelingSource`, no es un
 * único bloque compartido). Todos con "0 / false / lista vacía = sin
 * requisito", así que un guild que no los toque no nota absolutamente nada:
 * el bloque entero es opt-in.
 *
 * Existen para el abuso, no para la burocracia — el caso que los motiva es la
 * cuenta recién creada que entra, farmea nivel a base de mensajes de una letra
 * y se va.
 */
export interface DBLevelingRequirements {
	/**
	 * Segundos que el miembro debe llevar EN EL SERVIDOR antes de ganar XP.
	 * Sale de `joined_at` del miembro, que ya está en la caché de miembros:
	 * ninguna petición extra a Discord. 0 = sin requisito.
	 */
	min_membership_seconds: number;
	/**
	 * Antigüedad mínima de la CUENTA de Discord, en segundos. Se deduce del
	 * snowflake del propio id de usuario (los 42 bits altos son el timestamp),
	 * así que tampoco cuesta ninguna petición. 0 = sin requisito.
	 */
	min_account_age_seconds: number;
	/** SOLO TEXTO. Caracteres mínimos del mensaje, ya recortado. 0 = cualquiera. */
	min_message_length: number;
	/** SOLO TEXTO. Descarta el mensaje cuyo contenido, quitado el enlace, queda vacío. */
	ignore_link_only: boolean;
	/** SOLO TEXTO. Descarta el mensaje sin texto que solo trae adjuntos. */
	ignore_attachment_only: boolean;
	/** SOLO TEXTO. Descarta el mensaje que solo son emojis (unicode o custom) o un sticker. */
	ignore_sticker_or_emoji_only: boolean;
	/** SOLO TEXTO. Descarta el mensaje que empieza por el prefijo del servidor. */
	ignore_commands: boolean;
	/** Roles que se saltan TODOS los requisitos anteriores (staff, boosters…). */
	bypass_role_ids: string[];
}

/** Cuándo NO cuenta el tiempo en voz para ganar XP. */
export interface DBLevelingVoiceRules {
	/** Solo en el canal (o sólo con bots) no da XP. */
	ignore_alone: boolean;
	ignore_muted: boolean;
	ignore_deafened: boolean;
}

/**
 * Reglas de concesión de XP de UNA fuente (texto o voz): tasa, requisitos de
 * elegibilidad, exclusiones y multiplicadores. Los CUATRO modos de `xp_mode`
 * persisten SIEMPRE los dos bloques (`text` y `voice`) — el modo decide
 * cuáles CONCEDEN XP, no cuáles existen (ver la tabla de resolución en el
 * TSDoc de `DBModuleLeveling`).
 *
 * `interval_seconds` significa cosas distintas en cada fuente y por eso NO se
 * llama `cooldown`:
 *   - texto: ventana antispam; sólo el primer mensaje de la ventana da XP.
 *   - voz: duración del tick; cada tick completo en voz concede una tirada.
 *
 * Con `metric: "time"` (sólo tiene sentido en la fuente de VOZ) esta fuente
 * deja de tirar XP del todo: `min`/`max` no se usan y lo que gobierna el
 * nivel son los MINUTOS de `voice_seconds` — ver `LevelingVoiceMetric` y
 * `resolveVoiceMetric`.
 */
export interface DBLevelingSource {
	/**
	 * Qué magnitud mide esta fuente (ver `LevelingVoiceMetric`). Sólo tiene
	 * efecto en la fuente de VOZ; en el bloque de texto se IGNORA (siempre
	 * `"xp"`) y se persiste igual por simetría de forma, igual que
	 * `voice_rules` más abajo. Nunca se lee a pelo: resuélvelo con
	 * `resolveVoiceMetric`, que además fuerza `"xp"` en `xp_mode: "unified"`.
	 */
	metric: LevelingVoiceMetric;
	/** XP mínima por concesión. */
	min: number;
	/** XP máxima por concesión (>= min; igual a `min` = cantidad fija). */
	max: number;
	interval_seconds: number;
	requirements: DBLevelingRequirements;
	/** Canales donde no se gana XP con esta fuente. */
	excluded_channel_ids: string[];
	/** Quien tenga uno de estos roles no gana XP con esta fuente. */
	excluded_role_ids: string[];
	role_multipliers: DBLevelingMultiplier[];
	channel_multipliers: DBLevelingMultiplier[];
	/**
	 * Sólo se aplica a la fuente de voz; en el bloque de texto se IGNORA. Se
	 * persiste igual en los dos bloques por simetría de forma (y para que
	 * configurarlo en `voice` y luego cambiar de modo no pierda nada).
	 */
	voice_rules: DBLevelingVoiceRules;
}

/** Recompensas de nivel de UNA progresión: roles concedidos al alcanzar cada nivel de la lista. */
export interface DBLevelingRewards {
	enabled: boolean;
	stacking: LevelingRewardStacking;
	levels: DBLevelingReward[];
}

/** Aviso de subida de nivel de UNA progresión. */
export interface DBLevelingAnnounce {
	enabled: boolean;
	target: LevelingAnnounceTarget;
	/** Sólo se usa con `target: "channel"`. */
	channel_id: string | null;
	/** Tokens admitidos: {user} {mention} {level} {xp} {guild} {rank}. */
	content: string;
	/** Segundos hasta borrar el anuncio. `null` o `0` = no se borra. */
	delete_after_seconds: number | null;
}

/**
 * Curva, recompensas y anuncio de UNA progresión (un nivel). El número de
 * progresiones ACTIVAS lo decide `xp_mode`: una sola en `text_only`/
 * `voice_only`/`unified`, dos (`progression_text` + `progression_voice`) en
 * `separate`. Los cuatro modos persisten SIEMPRE los dos bloques.
 */
export interface DBLevelingProgression {
	/** `formula`: curva automática con `curve_multiplier`. `manual`: la tabla
	 *  de `manual_thresholds`. */
	curve_mode: LevelingCurveMode;
	/** Factor de dificultad de la curva cuando `curve_mode` es `"formula"`;
	 *  se ignora en `"manual"`. Ver `xpForNextLevel` en `leveling/curve.ts`.
	 *  Rango [0.01, 100]. */
	curve_multiplier: number;
	/**
	 * Umbrales ACUMULADOS, en orden ascendente: el índice 0 es lo que cuesta
	 * llegar al nivel 1, el índice 1 al nivel 2, etc. En XP, o en MINUTOS si
	 * la progresión mide tiempo (`LevelingVoiceMetric`).
	 *
	 * Al pasar del último umbral NO hay más niveles: el miembro se queda en
	 * el máximo definido y sigue acumulando XP/minutos sin subir. Es la
	 * decisión del dueño del proyecto, y hay que contarla en la interfaz.
	 *
	 * Lista vacía con `curve_mode: "manual"` = nadie pasa del nivel 0; es un
	 * estado válido (a medio configurar), no un error. Se ignora en
	 * `curve_mode: "formula"`.
	 */
	manual_thresholds: number[];
	rewards: DBLevelingRewards;
	announce: DBLevelingAnnounce;
}

/**
 * Config POR-GUILD del módulo de niveles (XP y rangos). El almacenamiento de
 * XP vive SIEMPRE en Postgres (`leveling.user_stats`, `text_xp`/`voice_xp`
 * separados); este documento es sólo la CONFIGURACIÓN.
 *
 * `xp_mode` es la PRIMERA decisión del admin y de ella depende la forma
 * entera de la interfaz. Cambiarla en el dashboard NUNCA destruye
 * configuración ni recalcula nada en masa (recálculo perezoso, ver
 * `leveling/curve.ts`): los CUATRO bloques (`text`, `voice`,
 * `progression_text`, `progression_voice`) se persisten SIEMPRE, los use o no
 * el modo activo. Qué bloque es el EFECTIVO para cada modo es una regla
 * ÚNICA — no reimplementar el switch en bot/dashboard, usar
 * `resolveLevelingScope`/`levelingProgressionFor`:
 *
 * | Modo         | Fuentes que conceden | Progresión(es) efectiva(s)                    |
 * |--------------|-----------------------|------------------------------------------------|
 * | `text_only`  | `text`                | `progression_text`                              |
 * | `voice_only` | `voice`               | `progression_voice`                             |
 * | `unified`    | `text` y `voice`      | `progression_text` (nivel = text_xp + voice_xp) |
 * | `separate`   | `text` y `voice`      | `progression_text` / `progression_voice`        |
 *
 * ⚠️ En `unified` la progresión activa es `progression_text` — deliberado:
 * evita un tercer bloque que sólo existiría para ese modo y hace que pasar de
 * `unified` a `separate` conserve la curva y las recompensas ya configuradas
 * (la de voz arranca con sus propios defaults). La interfaz NO llama a ese
 * bloque "Texto" en modo `unified`, lo llama "Progresión".
 */
export interface DBModuleLeveling {
	schema_version: number;
	enabled: boolean;
	/** Fecha de la PRIMERA activación (ISO-8601 UTC). WRITE-ONCE server-side. */
	enabled_since: string | null;
	xp_mode: LevelingXpMode;
	/** Reglas de concesión de XP por mensaje. Se persiste aunque el modo activo no la use. */
	text: DBLevelingSource;
	/** Reglas de concesión de XP por tiempo en voz. Se persiste aunque el modo activo no la use. */
	voice: DBLevelingSource;
	/** Progresión de texto. En `unified` es también la ÚNICA progresión activa (ver TSDoc de arriba). */
	progression_text: DBLevelingProgression;
	/** Progresión de voz. Efectiva sólo en `voice_only` y `separate`; se persiste igual en los demás modos. */
	progression_voice: DBLevelingProgression;
	/** Tarjeta ÚNICA de `/rank`; el ámbito con el que se invoque decide qué datos rellenan sus tokens (§3). */
	rank_card: {
		mode: LevelingCardMode;
		/** Modo `basic`: fondo y acento de la tarjeta de fábrica. */
		background_url: string | null;
		accent_color: string;
		/** Modo `advanced`: lienzo del editor. */
		canvas: DBGreeterImageCanvas;
	};
	/** Acceso GLOBAL de los comandos del módulo (mismo tipo que tempvoice). */
	commands_global: DBCommandAccess;
	/** Config por comando. Clave = nombre del comando (`rank`, `xp`, `top`). */
	commands: Record<string, DBLevelingCommand>;
	command_mode: LevelingCommandMode;
	updated_at: Date;
}

