func MarshalModuleGreeter(m dbguild.ModuleGreeter) (map[string]string, error) {
	out := map[string]string{}
	out["schema_version"] = SerializeValue(m.SchemaVersion)
	out["enabled"] = SerializeValue(m.Enabled)
