package dbguild

import (
	"encoding/json"
	"strings"
	"testing"

	"go.mongodb.org/mongo-driver/v2/bson"
)

// TestNormalizeTempvoice_NilCollectionsBecomeEmpty 🛡️ — a tempvoice decoded
// from a partial Mongo doc (nil slices / maps) must serialise its empty
// collections as `[]` / `{}`, never `null`, after NormalizeTempvoice. Nullable
// pointer scalars (parent_id, panel_channel_id, rtc_region, button emoji) stay
// `null`.
func TestNormalizeTempvoice_NilCollectionsBecomeEmpty(t *testing.T) {
	m := ModuleTempvoice{
		SchemaVersion: SchemaVersionTempvoice,
		// creators nil → []; a creator with nil moderator_role_ids → [].
		Creators: []TempvoiceCreator{
			{ChannelID: "c1"},
		},
		// name_blacklist nil, panel.buttons nil, commands_global lists nil.
		Commands: map[string]TempvoiceCommand{
			"limit": {}, // nested access-list IDs nil → must be normalised
		},
	}
	NormalizeTempvoice(&m)

	if m.NameBlacklist == nil {
		t.Fatalf("name_blacklist still nil after normalize")
	}
	if m.Panel.Buttons == nil {
		t.Fatalf("panel.buttons still nil")
	}
	if m.Creators[0].ModeratorRoleIDs == nil {
		t.Fatalf("creators[0].moderator_role_ids still nil")
	}
	if m.CommandsGlobal.Roles.IDs == nil || m.CommandsGlobal.Channels.IDs == nil || m.CommandsGlobal.Categories.IDs == nil {
		t.Fatalf("commands_global access-list IDs still nil")
	}
	cmd := m.Commands["limit"]
	if cmd.Access.Roles.IDs == nil || cmd.Access.Channels.IDs == nil || cmd.Access.Categories.IDs == nil {
		t.Fatalf("commands[limit] access-list IDs still nil")
	}

	b, err := json.Marshal(m)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	js := string(b)
	for _, bad := range []string{
		`"creators":null`, `"name_blacklist":null`, `"buttons":null`,
		`"commands":null`, `"ids":null`, `"moderator_role_ids":null`,
	} {
		if strings.Contains(js, bad) {
			t.Fatalf("normalized JSON must not contain %s:\n%s", bad, js)
		}
	}
	// Nullable pointer scalars are left as null (not coerced to "").
	if !strings.Contains(js, `"parent_id":null`) || !strings.Contains(js, `"rtc_region":null`) {
		t.Fatalf("nullable creator pointers should serialise as null:\n%s", js)
	}
}

