package dbguild

import (
	"encoding/json"
	"strings"
	"testing"
)

// TestNormalizeLeveling_RequirementsBypassRoleIDsBecomesEmpty 🛡️ — a leveling
// doc decoded from a partial Mongo document (or a stale cache entry) can
// bring `text.requirements.bypass_role_ids` / `voice.requirements.bypass_role_ids`
// as nil; NormalizeLeveling must backfill both to `[]` so the JSON body
// serialises `[]`, never `null` (same invariant as the module's other
// collection fields).
func TestNormalizeLeveling_RequirementsBypassRoleIDsBecomesEmpty(t *testing.T) {
	m := ModuleLeveling{
		SchemaVersion: SchemaVersionLeveling,
		Text:          LevelingXpSource{Requirements: LevelingRequirements{}},
		Voice:         LevelingXpSource{Requirements: LevelingRequirements{}},
	}
	NormalizeLeveling(&m)

	if m.Text.Requirements.BypassRoleIDs == nil {
		t.Fatalf("text.requirements.bypass_role_ids still nil after normalize")
	}
	if m.Voice.Requirements.BypassRoleIDs == nil {
		t.Fatalf("voice.requirements.bypass_role_ids still nil after normalize")
	}

	b, err := json.Marshal(m)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	if js := string(b); strings.Contains(js, `"bypass_role_ids":null`) {
		t.Fatalf("normalized JSON must not contain bypass_role_ids:null:\n%s", js)
	}
}

// TestNormalizeLeveling_RequirementsIdempotent 🛡️ — running NormalizeLeveling
// twice over an already-populated requirements block must not mutate or
// duplicate the bypass role list.
func TestNormalizeLeveling_RequirementsIdempotent(t *testing.T) {
	m := ModuleLeveling{
		SchemaVersion: SchemaVersionLeveling,
		Text: LevelingXpSource{
			Requirements: LevelingRequirements{BypassRoleIDs: []string{"staff"}},
		},
	}
	NormalizeLeveling(&m)
	NormalizeLeveling(&m)

	if got := m.Text.Requirements.BypassRoleIDs; len(got) != 1 || got[0] != "staff" {
		t.Fatalf("bypass_role_ids mutated by repeated normalize: %v", got)
	}
}

